// Group the day's new competitor ads by advertiser and prepare the Slack digest and the launch alert.
// Items follow the Google Ads Transparency Center Scraper dataset schema (type = "creative").
const settings = $('Workflow settings').first().json;
const RECENT_DAYS = Number(settings.recentDays) || 7;
const SPIKE_THRESHOLD = Number(settings.spikeThreshold) || 10;
const MAX_LINKS = 3;

const rows = $input.all().map((item) => item.json);
const today = new Date().toISOString().slice(0, 10);
const cutoff = Date.now() - RECENT_DAYS * 86400000;
const regions = String(settings.regions || '').trim() || 'anywhere';

// An ad counts as a launch when Google first showed it inside the recent window.
// Older ads delivered for the first time (the baseline run, or a large advertiser
// whose catalog is bigger than the cap) still reach the sheet and the digest,
// but never trigger the email alert.
const isLaunch = (row) => {
  const t = Date.parse(row.first_shown || '');
  return Number.isFinite(t) && t >= cutoff;
};

const groups = new Map();
for (const row of rows) {
  const key = row.advertiser_id || row.advertiser_name || row.domain || row.query || 'unknown';
  if (!groups.has(key)) {
    groups.set(key, {
      name: row.advertiser_name || row.domain || row.query || 'Unknown advertiser',
      domain: row.domain || '',
      advertiserId: row.advertiser_id || '',
      total: 0,
      launches: 0,
      formats: {},
      links: [],
    });
  }
  const group = groups.get(key);
  group.total += 1;
  if (isLaunch(row)) group.launches += 1;
  const format = row.format || 'other';
  group.formats[format] = (group.formats[format] || 0) + 1;
  const url = row.transparency_url || row.preview_url;
  if (url && group.links.length < MAX_LINKS) group.links.push(url);
}

const advertisers = [...groups.values()].sort((a, b) => b.launches - a.launches || b.total - a.total);
const spikes = advertisers.filter((a) => a.launches >= SPIKE_THRESHOLD);

const plural = (n, word) => `${n} ${word}${n === 1 ? '' : 's'}`;
const formatList = (formats) => Object.entries(formats).map(([format, n]) => `${n} ${format}`).join(', ');
const advertiserUrl = (a) => (a.advertiserId ? `https://adstransparency.google.com/advertiser/${a.advertiserId}?region=anywhere` : '');

const line = (a) => {
  const domain = a.domain && a.domain !== a.name ? ` (${a.domain})` : '';
  const launches = a.launches ? `, ${a.launches} first shown in the last ${plural(RECENT_DAYS, 'day')}` : '';
  const links = a.links.map((url, i) => `<${url}|ad ${i + 1}>`).join(' ');
  const all = advertiserUrl(a) ? ` <${advertiserUrl(a)}|all ads>` : '';
  return `• *${a.name}*${domain}: ${plural(a.total, 'new ad')} (${formatList(a.formats)})${launches} ${links}${all}`;
};

const message = [
  `:mag: *New competitor Google ads: ${regions}, ${today}*`,
  ...advertisers.map(line),
  `_${plural(rows.length, 'row')} appended to the sheet (ads not delivered before)._`,
].join('\n');

const lead = spikes[0];
const spikeSubject = lead
  ? `Competitor ad launch: ${lead.name} started ${plural(lead.launches, 'Google ad')} in ${plural(RECENT_DAYS, 'day')}`
  : '';
const spikeBody = lead
  ? [
      `These advertisers crossed your launch threshold of ${plural(SPIKE_THRESHOLD, 'ad')} first shown in the last ${plural(RECENT_DAYS, 'day')} (regions: ${regions}, ${today}):`,
      '',
      ...spikes.map((a) => `- ${a.name}${a.domain && a.domain !== a.name ? ' (' + a.domain + ')' : ''}: ${plural(a.launches, 'ad')} first shown in the last ${plural(RECENT_DAYS, 'day')}, ${plural(a.total, 'new row')} in total (${formatList(a.formats)})${advertiserUrl(a) ? ', ' + advertiserUrl(a) : ''}`),
      '',
      'The threshold, the window and this recipient live in the Workflow settings node of the n8n workflow.',
    ].join('\n')
  : '';

return [{ json: { newCount: rows.length, advertiserCount: advertisers.length, spikeCount: spikes.length, message, spikeSubject, spikeBody } }];
